select
  id, owner_id, owner_name, owner_number, owner_status, owner_id_card, sex, location, purpose, type, create_time, update_time, remark
from sys_owner


        and id = #{id}


        and owner_id = #{ownerId}


        and owner_name = #{ownerName}


        and owner_number = #{ownerNumber}


        and owner_status = #{ownerStatus}


        and owner_id_card = #{ownerIdCard}


        and sex = #{sex}


        and location = #{location}


        and purpose = #{purpose}


        and type = #{type}


        and create_time = #{createTime}


        and update_time = #{updateTime}


        and remark = #{remark}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from sys_owner


        and id = #{id}


        and owner_id = #{ownerId}


        and owner_name = #{ownerName}


        and owner_number = #{ownerNumber}


        and owner_status = #{ownerStatus}


        and owner_id_card = #{ownerIdCard}


        and sex = #{sex}


        and location = #{location}


        and purpose = #{purpose}


        and type = #{type}


        and create_time = #{createTime}


        and update_time = #{updateTime}


